/*
 * os-release(5) lookup, for the one thing PID 1 wants out of that file: the
 * name of the distribution to greet the console with (status.c).
 *
 * A subset of the format: KEY=value, optionally wrapped in one
 * matching pair of single or double quotes, with '#' comments and blank
 * lines. Backslash escapes inside a quoted value are NOT interpreted. The
 * file is generated by the image build, every value this reads out of it is a
 * plain string, and an unescaper is one more thing that can be wrong about a
 * value nothing escapes.
 *
 * Nothing here is fatal. This file lives on a machine-generated image, a
 * broken build can put anything in it, and none of that is worth a boot.
 */

#pragma once

/* Where os-release(5) says it lives, and where the image ships it. */
#define OS_RELEASE_PATH "/etc/os-release"

/*
 * Look `key` up in the os-release-format file at `path`, storing a freshly
 * allocated, unquoted value in *ret. Returns 0, or -ENOENT when the file or
 * the key is absent -- the two cases every caller here handles identically --
 * or another -errno. *ret is left untouched unless 0 is returned.
 *
 * A key assigned more than once takes its last value, as it would in the
 * shell this format borrows its syntax from.
 */
int os_release_get(const char *path, const char *key, char **ret);
